arguments.command:
python3 -c "
# Parse GMT file
pathways = {}
with open('/workspace/ReactomePathways.gmt', 'r') as f:
    for line in f:
        parts = line.strip().split('\t')
        pathway_name = parts[0]
        pathway_id = parts[1]
        genes = parts[2:]
        pathways[pathway_id] = {'name': pathway_name, 'genes': set(genes)}

print(f'Total pathways: {len(pathways)}')
# Find immune-relevant pathways
immune_keywords = ['immune', 'immun', 'T cell', 'B cell', 'NK cell', 'cytokine', 'interleukin', 'chemokine', 'mhc', 'hla', 'antigen', 'lymphocyte', 'macrophage', 'dendritic', 'neutrophil', 'eosinophil', 'basophil', 'mast cell', 'innate', 'adaptive']
immune_pathways = {}
for pid, pdata in pathways.items():
    name_lower = pdata['name'].lower()
    for kw in immune_keywords:
        if kw.lower() in name_lower:
            immune_pathways[pid] = pdata
            break
print(f'Immune-relevant pathways: {len(immune_pathways)}')
# Show a few examples
for i, (pid, pdata) in enumerate(list(immune_pathways.items())[:10]):
    print(f'{pid}: {pdata[\"name\"]} - {len(pdata[\"genes\"])} genes')
"

